1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	  li input[type="checkbox"] { width: 1.1rem; height: 1.1rem; margin: 0; cursor: pointer; }
52	  li[data-completed="true"] span { color: #a8a29e; text-decoration: line-through; }
53	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
54	  .filters button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
55	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
56	</style>
57	</head>
58	<body>
59	<main>
60	  <h1>Todos</h1>
61	  <form id="todo-form">
62	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
63	    <button type="submit" data-testid="todo-add">Add</button>
64	  </form>
65	  <div class="filters" role="group" aria-label="Filter todos">
66	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
67	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
68	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
69	  </div>
70	  <ul data-testid="todo-list"></ul>
71	</main>
72	<script>
73	(function () {
74	  var STORAGE_KEY = 'todos';
75	  var form = document.getElementById('todo-form');
76	  var input = document.querySelector('[data-testid="todo-input"]');
77	  var list = document.querySelector('[data-testid="todo-list"]');
78	
79	  // [REQ-001]
80	  function makeId() {
81	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
82	      return window.crypto.randomUUID();
83	    }
84	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
85	  }
86	
87	  // [REQ-001]
88	  function loadTodos() {
89	    try {
90	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
91	      return Array.isArray(parsed) ? parsed : [];
92	    } catch (e) {
93	      return [];
94	    }
95	  }
96	
97	  // [REQ-001]
98	  function saveTodos() {
99	    try {
100	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
101	    } catch (e) {}
102	  }
103	
104	  var todos = loadTodos();
105	  var filter = 'all';
106	  var filterButtons = document.querySelectorAll('[data-filter]');
107	
108	  // [REQ-002] Active todos first, then completed; each group keeps insertion order.
109	  function orderedTodos() {
110	    var active = todos.filter(function (t) { return !t.completed; });
111	    var done = todos.filter(function (t) { return !!t.completed; });
112	    return active.concat(done);
113	  }
114	
115	  // [REQ-002]
116	  function isVisible(todo) {
117	    if (filter === 'active') return !todo.completed;
118	    if (filter === 'completed') return !!todo.completed;
119	    return true;
120	  }
121	
122	  // [REQ-001]
123	  function render() {
124	    list.textContent = '';
125	    filterButtons.forEach(function (btn) {
126	      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
127	    });
128	    orderedTodos().filter(isVisible).forEach(function (todo) {
129	      var li = document.createElement('li');
130	      li.setAttribute('data-testid', 'todo-item');
131	      li.setAttribute('data-id', todo.id);
132	      li.setAttribute('data-completed', String(!!todo.completed));
133	
134	      var toggle = document.createElement('input');
135	      toggle.type = 'checkbox';
136	      toggle.setAttribute('data-testid', 'todo-toggle');
137	      toggle.setAttribute('aria-label', 'Mark complete');
138	      toggle.checked = !!todo.completed;
139	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
140	      li.appendChild(toggle);
141	
142	      var text = document.createElement('span');
143	      text.setAttribute('data-testid', 'todo-text');
144	      text.textContent = todo.text;
145	
146	      var del = document.createElement('button');
147	      del.type = 'button';
148	      del.setAttribute('data-testid', 'todo-delete');
149	      del.setAttribute('aria-label', 'Delete todo');
150	      del.textContent = 'Delete';
151	      del.addEventListener('click', function () { deleteTodo(todo.id); });
152	
153	      li.appendChild(text);
154	      li.appendChild(del);
155	      list.appendChild(li);
156	    });
157	  }
158	
159	  // [REQ-001]
160	  function addTodo(text) {
161	    text = text.trim();
162	    if (!text) return;
163	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false });
164	    saveTodos();
165	    render();
166	  }
167	
168	  // [REQ-002]
169	  function toggleTodo(id) {
170	    todos.forEach(function (t) {
171	      if (t.id === id) t.completed = !t.completed;
172	    });
173	    saveTodos();
174	    render();
175	  }
176	
177	  // [REQ-002]
178	  function setFilter(value) {
179	    filter = value;
180	    render();
181	  }
182	
183	  filterButtons.forEach(function (btn) {
184	    btn.addEventListener('click', function () { setFilter(btn.getAttribute('data-filter')); });
185	  });
186	
187	  // [REQ-001]
188	  function deleteTodo(id) {
189	    todos = todos.filter(function (t) { return t.id !== id; });
190	    saveTodos();
191	    render();
192	  }
193	
194	  form.addEventListener('submit', function (e) {
195	    e.preventDefault();
196	    addTodo(input.value);
197	    input.value = '';
198	    input.focus();
199	  });
200	
201	  render();
202	})();
203	</script>
204	</body>
205	</html>
